arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Authorization: Bearer <TOKEN>' -d 'exclude_archived=true&limit=1000' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for c in d['channels']:
    topic=c.get('topic',{}) or {}
    print(c['id'], '|', c.get('name'), '|', topic.get('value',''))
"

