arguments.command:
curl -s -X POST https://slack.com/api/users.list -H 'Authorization: Bearer <TOKEN>' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for u in d['members']:
    if not u.get('is_bot') and 'aisha' in (u.get('real_name','')+u.get('profile',{}).get('display_name','')).lower():
        print(u['id'], '|', u.get('real_name'), '|', u.get('profile',{}).get('display_name'))
"

